begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at)values('f1310000-0000-0000-0000-000000000001','handoff-owner@test.invalid',now());
insert into public.tenants(id,name,slug)values('f1311000-0000-0000-0000-000000000001','Handoff QA','handoff-qa-131');
insert into public.tenant_memberships(tenant_id,user_id,role)values('f1311000-0000-0000-0000-000000000001','f1310000-0000-0000-0000-000000000001','owner');
insert into public.properties(id,tenant_id,name,property_type)values('f1312000-0000-0000-0000-000000000001','f1311000-0000-0000-0000-000000000001','Handoff Hotel','hotel');
insert into public.whatsapp_connections(id,tenant_id,property_id,phone_number_id,waba_id,credentials_ref)values('f1313000-0000-0000-0000-000000000001','f1311000-0000-0000-0000-000000000001','f1312000-0000-0000-0000-000000000001','13100000001','13100000002','synthetic');
update public.whatsapp_default_setup set lease='f1314000-0000-0000-0000-000000000001',locked_at=now()where property_id='f1312000-0000-0000-0000-000000000001';
insert into public.conversations(id,tenant_id,property_id,connection_id,wa_contact_id,human_handoff)values('f1315000-0000-0000-0000-000000000001','f1311000-0000-0000-0000-000000000001','f1312000-0000-0000-0000-000000000001','f1313000-0000-0000-0000-000000000001','919000000131',true);
select is((select handoff_changed_at from public.conversations where id='f1315000-0000-0000-0000-000000000001'),null::timestamptz,'Historical pause receives no invented timestamp');
select is((select handoff_actor_name from public.conversations where id='f1315000-0000-0000-0000-000000000001'),null::text,'Historical pause receives no invented actor');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1310000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.record_whatsapp_default_failure('f1312000-0000-0000-0000-000000000001','f1314000-0000-0000-0000-000000000001','booking_changed','Meta rejected variable density')$$,'42501',null,'Browser cannot forge template setup errors');
select public.inbox_manage('f1315000-0000-0000-0000-000000000001',(select version from public.conversations where id='f1315000-0000-0000-0000-000000000001'),'human_off');
select is((select human_handoff from public.conversations where id='f1315000-0000-0000-0000-000000000001'),false,'Explicit owner action resumes only this chat');
select is((select handoff_origin from public.conversations where id='f1315000-0000-0000-0000-000000000001'),'staff','Future staff changes record their origin');
select is((select handoff_actor_id from public.conversations where id='f1315000-0000-0000-0000-000000000001'),'f1310000-0000-0000-0000-000000000001'::uuid,'The authenticated staff actor is recorded');
select ok((select handoff_changed_at is not null from public.conversations where id='f1315000-0000-0000-0000-000000000001'),'Future handoff changes record the time');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
update public.conversations set human_handoff=true where id='f1315000-0000-0000-0000-000000000001';
select is((select handoff_origin from public.conversations where id='f1315000-0000-0000-0000-000000000001'),'automation','Automated handoff is distinguished from a staff action');
select is((select handoff_actor_id from public.conversations where id='f1315000-0000-0000-0000-000000000001'),null::uuid,'Automated handoff does not name a staff member');
select set_config('test.handoff_time',(select handoff_changed_at::text from public.conversations where id='f1315000-0000-0000-0000-000000000001'),true);
update public.conversations set last_inbound_at=now()where id='f1315000-0000-0000-0000-000000000001';
select is((select handoff_changed_at::text from public.conversations where id='f1315000-0000-0000-0000-000000000001'),current_setting('test.handoff_time'),'Receiving a message does not rewrite the pause provenance');
set local role service_role;
select lives_ok($$select public.record_whatsapp_default_failure('f1312000-0000-0000-0000-000000000001','f1314000-0000-0000-0000-000000000001','booking_changed','Meta 100 / 2388293: Too many variables.')$$,'Worker can record an actionable per-template error');
select throws_ok($$select public.record_whatsapp_default_failure('f1312000-0000-0000-0000-000000000001',gen_random_uuid(),'booking_changed','Stale setup lease')$$,'40001',null,'An old worker cannot overwrite the current lease');
reset role;
select is((select state from public.whatsapp_default_templates where property_id='f1312000-0000-0000-0000-000000000001'and slot='booking_changed'),'queued','A failed create remains eligible for safe name reconciliation');
select ok((select last_error like '%2388293%'from public.whatsapp_default_templates where property_id='f1312000-0000-0000-0000-000000000001'and slot='booking_changed'),'The owner can see the actionable provider rejection');
select is((select last_error from public.whatsapp_default_templates where property_id='f1312000-0000-0000-0000-000000000001'and slot='checked_in'),null::text,'An unrelated starter remains unaffected');
select *from finish();
rollback;
